function [u_c_ref_ab_out, w] = mfun_fvc_modulate(fbk_in, u_s_in, standby, p)
%MFUN_FVC_MODULATE Block modulate of the control system.
%   Generated by motulator_export from the MATLAB port of motulator and called by the
%   MATLAB Function block of the library of motulator, whose folder motulator.setup adds
%   to the MATLAB path. The parameters are the fields of the struct p (from the mask, []
%   as NaN).
fbk = observer_outputs_unpack(fbk_in);
u_s = complex_in(u_s_in);
% Voltage reference in stationary coordinates, its angle advanced by
% k_comp*T_s*w_c (k_comp = 1.5 of the controller)
u_c_ref_ab = exp(1i*fbk.theta_c)*u_s;
u_c_ref_ab = u_c_ref_ab*exp(1i*1.5*p.T_s*fbk.w_c);
% The zero vector of a sensorless drive in standby
if p.sensorless > 0 && standby ~= 0
    u_c_ref_ab = complex(0);
end
w = fbk.w_c;
u_c_ref_ab_out = complex_out(u_c_ref_ab);
end

function s = observer_outputs_unpack(u)
%OBSERVER_OUTPUTS_UNPACK Struct of the signal vector u.
s = struct( ...
    'i_s', complex(u(1), u(2)), ...
    'u_s', complex(u(3), u(4)), ...
    'u_s_zoh', complex(u(5), u(6)), ...
    'psi_s', complex(u(7), u(8)), ...
    'e_o', complex(u(9), u(10)), ...
    'eps', u(11), ...
    'eps_f', u(12), ...
    'psi_a', complex(u(13), u(14)), ...
    'tau_M', u(15), ...
    'w_c', u(16), ...
    'w_m', u(17), ...
    'w_M', u(18), ...
    'theta_c', u(19), ...
    'theta_m', u(20), ...
    'psi_f', u(21), ...
    'h', u(22), ...
    'caught', u(23));
end

function z = complex_in(u)
%COMPLEX_IN Complex number from a signal [real part; imaginary part].
z = complex(u(1), u(2));
end

function y = complex_out(z)
%COMPLEX_OUT Signal [real part; imaginary part] of a complex number.
y = [real(z); imag(z)];
end
